// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(1, 42, 100, keccak256("test"), 1, keccak256("batcher"), 1000, 2000);
        uint256 stored = c.timestamp();
        assertTrue(stored == 42, "timestamp should be 42 after setL1BlockValues");
    }
}
